import React, { useState } from 'react'

function App() {
  const [projects, setProjects] = useState([
    { titre: 'Portfolio', description: 'Site personnel pour présenter mes projets.' },
    { titre: 'ToDo App', description: 'Application de gestion de tâches avec React.' }
  ])

  const [titre, setTitre] = useState('')
  const [description, setDescription] = useState('')

  const handleSubmit = (e) => {
    e.preventDefault()
    if (!titre || !description) return
    setProjects([...projects, { titre, description }])
    setTitre('')
    setDescription('')
  }

  return (
    <div style={{ fontFamily: 'sans-serif', padding: '2rem', maxWidth: '800px', margin: '0 auto' }}>
      <section style={{ textAlign: 'center' }}>
        <img src="https://via.placeholder.com/150" alt="Moi" style={{ borderRadius: '50%' }} />
        <h1>Jean Dupont</h1>
        <p>Développeur passionné par le web et les nouvelles technologies</p>
      </section>

      <section style={{ marginTop: '3rem' }}>
        <h2>Mes Projets</h2>
        <ul>
          {projects.map((projet, index) => (
            <li key={index} style={{ marginBottom: '1rem' }}>
              <strong>{projet.titre}</strong> – {projet.description}
            </li>
          ))}
        </ul>
      </section>

      <section style={{ marginTop: '3rem' }}>
        <h2>Ajouter un projet</h2>
        <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1rem' }}>
          <input
            type="text"
            placeholder="Titre"
            value={titre}
            onChange={(e) => setTitre(e.target.value)}
            style={{ padding: '0.5rem' }}
          />
          <textarea
            placeholder="Description"
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            style={{ padding: '0.5rem' }}
          ></textarea>
          <button type="submit" style={{ padding: '0.5rem', backgroundColor: '#333', color: '#fff' }}>
            Ajouter
          </button>
        </form>
      </section>
    </div>
  )
}

export default App
